import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TreeTraversingParser.getLongValue().
 * Since TreeTraversingParser is a complex class that relies on internal state 
 * of the JsonNode it traverses, we use a real ObjectMapper to create the parser 
 * to ensure the internal 'currentNumericNode' is set correctly.
 */
public class TreeTraversingParser_getLongValue_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }







    /**
     * Tests getLongValue when the current node is not a NumericNode.
     * This tests the behavior/exception when the cast (NumericNode) currentNumericNode() fails.
     */
    @Test(expected = ClassCastException.class)
    public void testGetLongValue_NotANumericNode() throws IOException {
        JsonNode node = JsonNodeFactory.instance.textNode("not a number");

        try (TreeTraversingParser parser = new TreeTraversingParser(node, mapper)) {
            parser.getLongValue();
        }
    }


}

